insert into public.sentences (text, text_zh, notebook_id) values ('Writing is the art of repeating oneself without anyone noticing.', '写作是重复自己而不被人察觉的艺术。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('Most people write so they can remember things; I write to forget.', '大多数人写作是为了记住事情；我写作是为了遗忘。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('What they call philosophy I call literature; what they call literature I call journalism; what they call journalism I call gossip; and what they call gossip I call (generously) voyeurism.', '他们称之为哲学的，我称之为文学；他们称之为文学的，我称之为新闻；他们称之为新闻的，我称之为八卦；他们称之为八卦的，我（慷慨地）称之为窥视癖。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('Writers are remembered for their best work, politicians for their worst mistakes, and businessmen are almost never remembered.', '作家因最佳作品被铭记，政治家因最糟错误被铭记，而商人几乎从不被铭记。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('Critics may appear to blame the author for not writing the book they wanted to read; but in truth they are blaming him for writing the book they wanted, but were unable, to write.', '批评家似乎在责怪作者没有写出他们想读的书；但实际上他们是在责怪作者写出了他们想写却写不出的书。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('Literature is not about promoting qualities, rather, airbrushing (your) defects.', '文学不是为了宣扬品质，而是为了修饰（你的）缺陷。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('For pleasure, read one chapter by Nabokov. For punishment, two.', '为了愉悦，读纳博科夫的一章。为了惩罚，读两章。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('There is a distinction between expressive hypochondria and literature, just as there is one between selfhelp and philosophy.', '表达性疑病症与文学之间有区别，正如自助与哲学之间有区别一样。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('You need to keep reminding yourself of the obvious: charm lies in the unsaid, the unwritten, and the undisplayed. It takes mastery to control silence.', '你需要不断提醒自己这个显而易见的道理：魅力在于未说出的、未写出的和未展示的。控制沉默需要精湛的技艺。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('No author should be considered as having failed until he starts teaching others about writing.', '没有作者应该被认为失败，直到他开始教别人写作。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('Hard science gives sensational results with a horribly boring process; philosophy gives boring results with a sensational process; literature gives sensational results with a sensational process; and economics gives boring results with a boring process.', '硬科学用极其无聊的过程产生轰动的结果；哲学用轰动的过程产生无聊的结果；文学用轰动的过程产生轰动的结果；而经济学用无聊的过程产生无聊的结果。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('A good maxim allows you to have the last word without even starting a conversation.', '一个好的格言让你不用开始对话就能说出最后一句话。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('Just as there are authors who enjoy having written and others who enjoy writing, there are books you enjoy reading and others you enjoy having read.', '正如有些作者享受已经写完的状态，有些享受写作过程，有些书你享受阅读，有些你享受已经读完的状态。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('A genius is someone with flaws harder to imitate than his qualities.', '天才是那种缺陷比品质更难模仿的人。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('With regular books, read the text and skip the footnotes; with those written by academics, read the footnotes and skip the text; and with business books, skip both the text and the footnotes.', '对于普通书籍，读正文跳过脚注；对于学者写的书，读脚注跳过正文；对于商业书籍，正文和脚注都跳过。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('Double a man''s erudition; you will halve his citations.', '让一个人的博学翻倍；你会让他的引用减半。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('Losers, when commenting on the works of someone patently more impressive, feel obligated to unnecessarily bring down their subject by expressing what he is not ("he is not a genius, but …"; "while he is no Leonardo …") instead of expressing what he is.', '失败者在评论明显更出色的人的作品时，觉得有义务通过表达他不是什么来不必要地贬低对象（"他不是天才，但是..."；"虽然他不是达芬奇..."），而不是表达他是什么。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('You are alive in inverse proportion to the density of clichés in your writing.', '你的活力与你写作中陈词滥调的密度成反比。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('What we call "business books" is an eliminative category invented by bookstores for writings that have no depth, no style, no empirical rigor, and no linguistic sophistication.', '我们所说的"商业书籍"是书店发明的一个排除性类别，用于那些没有深度、没有风格、没有实证严谨性和没有语言精致性的著作。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('Just like poets and artists, bureaucrats are born, not made; it takes normal humans extraordinary effort to keep attention on such boring tasks.', '就像诗人和艺术家一样，官僚是天生的，不是后天培养的；普通人需要非凡的努力才能将注意力保持在如此无聊的任务上。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('The costs of specialization: architects build to impress other architects; models are thin to impress other models; academics write to impress other academics; filmmakers try to impress other filmmakers; painters impress art dealers; but authors who write to impress book editors tend to fail.', '专业化的代价：建筑师建造是为了打动其他建筑师；模特瘦身是为了打动其他模特；学者写作是为了打动其他学者；电影制作人试图打动其他电影制作人；画家打动艺术经销商；但为了打动图书编辑而写作的作者往往会失败。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('It is a waste of emotions to answer critics; better to stay in print long after they are dead.', '回应批评者是浪费情感；最好是在他们死后很久还能保持印刷出版。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('I can predict when an author is about to plagiarize me, and poorly so when he writes that Taleb "popularized" the theory of Black Swan events.', '我能预测作者何时要抄袭我，而且抄得很糟，当他写塔勒布"普及"了黑天鹅事件理论时。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('Newspaper readers exposed to real prose are like deaf persons at a Puccini opera: they may like a thing or two while wondering, "what''s the point?"', '接触真正散文的报纸读者就像在普契尼歌剧院的聋人：他们可能喜欢一两样东西，同时疑惑"有什么意义？"', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('Some books cannot be summarized (real literature, poetry); some can be compressed to about ten pages; the majority to zero pages.', '有些书无法总结（真正的文学、诗歌）；有些可以压缩到大约十页；大多数可以压缩到零页。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('The exponential information age is like a verbally incontinent person: he talks more and more as fewer and fewer people listen.', '指数信息时代就像一个言语失禁的人：他说得越来越多，听的人却越来越少。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('What we call fiction is, when you look deep, much less fictional than nonfiction; but it is usually less imaginative.', '我们称之为小说的东西，深入观察时，比非小说更不虚构；但通常更缺乏想象力。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('It''s much harder to write a book review for a book you''ve read than for a book you haven''t read.', '为你读过的书写书评比为你没读过的书写书评要难得多。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('Most socalled writers keep writing and writing with the hope to, some day, find something to say.', '大多数所谓的作家不断地写啊写，希望有一天能找到要说的东西。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('Today, we mostly face the choice between those who write clearly about a subject they don''t understand and those who write poorly about a subject they don''t understand.', '今天，我们主要面临的选择是：那些对不理解的主题写得清楚的人，和那些对不理解的主题写得糟糕的人。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('The informationrich Dark Ages: in 2010, 600,000 books were published, just in English, with few memorable quotes. Circa AD zero, a handful of books were written. In spite of the few that survived, there are loads of quotes.', '信息丰富的黑暗时代：2010年，仅英语就出版了60万本书，却很少有令人难忘的引语。公元零年左右，只写了少数几本书。尽管幸存的很少，却有大量的引语。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('In the past, most were ignorant, one in a thousand were refined enough to talk to. Today, literacy is higher, but thanks to progress, the media, and finance, only one in ten thousand.', '过去，大多数人无知，千分之一的人足够优雅可以交谈。今天，识字率更高，但由于进步、媒体和金融，只有万分之一。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('We are better at (involuntarily) doing out of the box than (voluntarily) thinking out of the box.', '我们更擅长（无意识地）跳出框框行动，而不是（有意识地）跳出框框思考。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('Half of suckerhood is not realizing that what you don''t like might be loved by someone else (hence by you, later), and the reverse.', '愚蠢的一半是没有意识到你不喜欢的东西可能被别人喜爱（因此以后也可能被你喜爱），反之亦然。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('It is much less dangerous to think like a man of action than to act like a man of thought.', '像行动者那样思考比像思想者那样行动要安全得多。', 29);
insert into public.sentences (text, text_zh, notebook_id) values ('Literature comes alive when covering up vices, defects, weaknesses, and confusions; it dies with every trace of preaching.', '文学在掩盖恶习、缺陷、弱点和困惑时变得生动；在每一丝说教中死去。', 29);